#include <Arduino.h>
#include <WiFi.h>
#include "esp_camera.h"
#include "esp_http_server.h"

namespace {
constexpr char AP_SSID[] = "GerNetiX-Camera";
constexpr char AP_PASSWORD[] = "camera-demo-2026"; // Vor echtem Einsatz ändern.

constexpr int CAM_PIN_PWDN = 32;
constexpr int CAM_PIN_RESET = -1;
constexpr int CAM_PIN_XCLK = 0;
constexpr int CAM_PIN_SIOD = 26;
constexpr int CAM_PIN_SIOC = 27;
constexpr int CAM_PIN_D7 = 35;
constexpr int CAM_PIN_D6 = 34;
constexpr int CAM_PIN_D5 = 39;
constexpr int CAM_PIN_D4 = 36;
constexpr int CAM_PIN_D3 = 21;
constexpr int CAM_PIN_D2 = 19;
constexpr int CAM_PIN_D1 = 18;
constexpr int CAM_PIN_D0 = 5;
constexpr int CAM_PIN_VSYNC = 25;
constexpr int CAM_PIN_HREF = 23;
constexpr int CAM_PIN_PCLK = 22;

constexpr char STREAM_TYPE[] = "multipart/x-mixed-replace;boundary=frame";
constexpr char STREAM_BOUNDARY[] = "\r\n--frame\r\n";
constexpr char STREAM_PART[] = "Content-Type: image/jpeg\r\nContent-Length: %u\r\n\r\n";

httpd_handle_t pageServer = nullptr;
httpd_handle_t streamServer = nullptr;

esp_err_t pageHandler(httpd_req_t *request) {
  const char page[] = "<!doctype html><meta name='viewport' content='width=device-width'><title>GerNetiX Camera</title><style>body{font-family:sans-serif;background:#111;color:#eee;text-align:center}img{max-width:100%;height:auto}</style><h1>ESP32-Kamera</h1><img src='http://192.168.4.1:81/stream' alt='Kamerastream'>";
  httpd_resp_set_type(request, "text/html; charset=utf-8");
  return httpd_resp_send(request, page, HTTPD_RESP_USE_STRLEN);
}

esp_err_t streamHandler(httpd_req_t *request) {
  esp_err_t result = httpd_resp_set_type(request, STREAM_TYPE);
  char header[96];
  while (result == ESP_OK) {
    camera_fb_t *frame = esp_camera_fb_get();
    if (!frame) return ESP_FAIL;
    const size_t headerLength = snprintf(header, sizeof(header), STREAM_PART, frame->len);
    result = httpd_resp_send_chunk(request, STREAM_BOUNDARY, strlen(STREAM_BOUNDARY));
    if (result == ESP_OK) result = httpd_resp_send_chunk(request, header, headerLength);
    if (result == ESP_OK) result = httpd_resp_send_chunk(request, reinterpret_cast<const char *>(frame->buf), frame->len);
    esp_camera_fb_return(frame);
  }
  return result;
}

bool startCamera() {
  camera_config_t config = {};
  config.ledc_channel = LEDC_CHANNEL_0;
  config.ledc_timer = LEDC_TIMER_0;
  config.pin_d0 = CAM_PIN_D0; config.pin_d1 = CAM_PIN_D1;
  config.pin_d2 = CAM_PIN_D2; config.pin_d3 = CAM_PIN_D3;
  config.pin_d4 = CAM_PIN_D4; config.pin_d5 = CAM_PIN_D5;
  config.pin_d6 = CAM_PIN_D6; config.pin_d7 = CAM_PIN_D7;
  config.pin_xclk = CAM_PIN_XCLK; config.pin_pclk = CAM_PIN_PCLK;
  config.pin_vsync = CAM_PIN_VSYNC; config.pin_href = CAM_PIN_HREF;
  config.pin_sccb_sda = CAM_PIN_SIOD; config.pin_sccb_scl = CAM_PIN_SIOC;
  config.pin_pwdn = CAM_PIN_PWDN; config.pin_reset = CAM_PIN_RESET;
  config.xclk_freq_hz = 20000000;
  config.pixel_format = PIXFORMAT_JPEG;
  config.frame_size = psramFound() ? FRAMESIZE_VGA : FRAMESIZE_QVGA;
  config.jpeg_quality = 12;
  config.fb_count = psramFound() ? 2 : 1;
  config.grab_mode = CAMERA_GRAB_LATEST;
  config.fb_location = psramFound() ? CAMERA_FB_IN_PSRAM : CAMERA_FB_IN_DRAM;
  return esp_camera_init(&config) == ESP_OK;
}

void startServers() {
  httpd_config_t pageConfig = HTTPD_DEFAULT_CONFIG();
  httpd_start(&pageServer, &pageConfig);
  const httpd_uri_t pageUri = { .uri = "/", .method = HTTP_GET, .handler = pageHandler, .user_ctx = nullptr };
  httpd_register_uri_handler(pageServer, &pageUri);

  httpd_config_t streamConfig = HTTPD_DEFAULT_CONFIG();
  streamConfig.server_port = 81;
  streamConfig.ctrl_port = 32769;
  httpd_start(&streamServer, &streamConfig);
  const httpd_uri_t streamUri = { .uri = "/stream", .method = HTTP_GET, .handler = streamHandler, .user_ctx = nullptr };
  httpd_register_uri_handler(streamServer, &streamUri);
}
}

void setup() {
  Serial.begin(115200);
  if (!startCamera()) { Serial.println("Kamera konnte nicht initialisiert werden."); return; }
  camera_fb_t *firstFrame = esp_camera_fb_get();
  if (firstFrame) {
    Serial.printf("Erster JPEG-Frame: %u Byte\n", static_cast<unsigned>(firstFrame->len));
    esp_camera_fb_return(firstFrame);
  }
  WiFi.mode(WIFI_AP);
  if (!WiFi.softAP(AP_SSID, AP_PASSWORD)) { Serial.println("Access Point konnte nicht gestartet werden."); return; }
  startServers();
  Serial.printf("Öffne http://%s/ im Smartphone-Browser.\n", WiFi.softAPIP().toString().c_str());
}

void loop() { delay(1000); }
